<script lang="ts">
import type { Snippet } from 'svelte';
import { untrack, tick, onMount, onDestroy } from 'svelte';
import type { TableContract } from '@unofficial-krds/contracts';
import { owned, control, resetField, ignoredKey } from './catalog-state.svelte.js';
let p: TableContract  = $props();
function validate(){if(p.rowHeaderColumnId&&!p.columns.some(column=>column.id===p.rowHeaderColumnId))throw new TypeError('rowHeaderColumnId must identify an existing column');}validate();$effect(validate);let region:HTMLDivElement;let overflow=$state(false);onMount(()=>{const update=()=>overflow=region.scrollWidth>region.clientWidth+1;const observer=new ResizeObserver(update);observer.observe(region);update();return()=>observer.disconnect();});const uid=$props.id();function sort(id:string){p.onSortChange?.({columnId:id,direction:p.sort?.columnId===id&&p.sort.direction==='ascending'?'descending':'ascending'});}
</script>
<div {...owned('table','root',p.sort?.direction)}><!-- svelte-ignore a11y_no_noninteractive_tabindex (A named overflow region receives native keyboard scroll focus.) -->
